"use strict";(()=>{const search=document.getElementById("brand-search");if(!search)return;const cards=[...document.querySelectorAll("[data-brand-name]")],buttons=[...document.querySelectorAll("[data-brand-filter]")];let sport="all";function render(){const term=search.value.trim().toLowerCase();let count=0;cards.forEach(card=>{const show=(sport==="all"||card.dataset.brandSports.split(" ").includes(sport))&&card.dataset.brandName.toLowerCase().includes(term);card.hidden=!show;if(show)count++});buttons.forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.brandFilter===sport)));document.getElementById("brand-results-count").textContent=`${count} ${count===1?"brand":"brands"} to explore`;document.getElementById("brand-empty").hidden=count>0}buttons.forEach(button=>button.addEventListener("click",()=>{sport=button.dataset.brandFilter;render()}));search.addEventListener("input",render);document.getElementById("reset-brand-filters").addEventListener("click",()=>{sport="all";search.value="";render();search.focus()});render()})();